enum Expr { Num(f64), Add(Box<Expr>, Box<Expr>) }

fn eval(e: &Expr) -> f64 {
    match e {                          // a new operation is a new function
        Expr::Num(v) => *v,
        Expr::Add(l, r) => eval(l) + eval(r),
    }
}
