trait Visitor {
    fn visit_expr(&mut self, e: &Expr) { walk_expr(self, e) }   // default walk
    fn visit_num(&mut self, _v: f64) {}
}
fn walk_expr<V: Visitor + ?Sized>(v: &mut V, e: &Expr) {
    match e { Expr::Num(n) => v.visit_num(*n),
              Expr::Add(l, r) => { v.visit_expr(l); v.visit_expr(r); } }
}

struct Counter { nums: u32 }
impl Visitor for Counter { fn visit_num(&mut self, _v: f64) { self.nums += 1; } }
